/**
 * The client, one per profile. Every call returns without blocking on I/O;
 * `now` is Unix milliseconds on the device clock.
 */
public protocol EngineProtocol: AnyObject, Sendable {
    
    /**
     * Accepts a friend request.
     */
    func accept(peer: String)  -> [Effect]
    
    /**
     * Blocks a user.
     */
    func block(peer: String)  -> [Effect]
    
    /**
     * Creates the device key and a new identity.
     */
    func createIdentity() throws  -> [Effect]
    
    /**
     * Deletes the account, then this profile's data.
     */
    func deleteAccount()  -> [Effect]
    
    /**
     * The safety number for a friend.
     */
    func fingerprint(peer: String)  -> String?
    
    /**
     * The friends, sorted for display.
     */
    func friends()  -> [FriendView]
    
    /**
     * A page of a conversation, newest last.
     */
    func history(peer: String, before: Int64?, limit: UInt32) throws  -> [Message]
    
    /**
     * Sends a friend request.
     */
    func invite(username: String)  -> [Effect]
    
    /**
     * Friend requests waiting for an answer.
     */
    func invites()  -> [InviteView]
    
    /**
     * Forget the opened secrets.
     */
    func lock()  -> [Effect]
    
    /**
     * Bytes arrived on a connection.
     */
    func onBytes(conn: UInt64, bytes: Data, now: Int64)  -> [Effect]
    
    /**
     * A connection closed or failed to open.
     */
    func onClosed(conn: UInt64, reason: CloseReason, now: Int64)  -> [Effect]
    
    /**
     * The answer to an `Effect::Http`.
     */
    func onHttp(req: UInt64, status: UInt16, body: Data, now: Int64)  -> [Effect]
    
    /**
     * The device moved to another network.
     */
    func onNetworkChanged(network: NetworkInfo, now: Int64)  -> [Effect]
    
    /**
     * A connection from `Effect::Open` is up.
     */
    func onOpened(conn: UInt64, now: Int64)  -> [Effect]
    
    /**
     * Registers for push wake-ups.
     */
    func registerPush(token: PushToken)  -> [Effect]
    
    /**
     * Removes a friend.
     */
    func remove(peer: String)  -> [Effect]
    
    /**
     * Reports a friend's messages.
     */
    func report(report: ReportInput)  -> [Effect]
    
    /**
     * Resends a failed message under its id.
     */
    func retry(msgId: String, now: Int64)  -> [Effect]
    
    /**
     * Sends `text` to a friend.
     */
    func sendText(peer: String, text: String, now: Int64) throws  -> [Effect]
    
    /**
     * Claims a username.
     */
    func setUsername(username: String)  -> [Effect]
    
    /**
     * Starts (and resumes): signs in, connects, re-reads what changed.
     */
    func start(now: Int64, network: NetworkInfo)  -> [Effect]
    
    /**
     * A timer fired, or the app resumed.
     */
    func tick(now: Int64)  -> [Effect]
    
    /**
     * The shell authenticated the user.
     */
    func unlock(now: Int64) throws  -> [Effect]
    
}
