/**
 * A user action that goes to the server.
 */

public enum Action: Equatable, Hashable {
    
    /**
     * Sign-in or refresh.
     */
    case signIn
    /**
     * Claiming a username.
     */
    case setUsername
    /**
     * A friend request.
     */
    case invite
    /**
     * Accepting one.
     */
    case accept
    /**
     * Removing a friend.
     */
    case remove
    /**
     * Blocking.
     */
    case block
    /**
     * A report.
     */
    case report
    /**
     * Deleting the account.
     */
    case deleteAccount
    /**
     * Registering for push.
     */
    case registerPush
    /**
     * Publishing prekeys.
     */
    case publishPrekeys





}

