extension Action: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAction: FfiConverterRustBuffer {
    typealias SwiftType = Action

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Action {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .signIn
        
        case 2: return .setUsername
        
        case 3: return .invite
        
        case 4: return .accept
        
        case 5: return .remove
        
        case 6: return .block
        
        case 7: return .report
        
        case 8: return .deleteAccount
        
        case 9: return .registerPush
        
        case 10: return .publishPrekeys
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Action, into buf: inout [UInt8]) {
        switch value {
        
        
        case .signIn:
            writeInt(&buf, Int32(1))
        
        
        case .setUsername:
            writeInt(&buf, Int32(2))
        
        
        case .invite:
            writeInt(&buf, Int32(3))
        
        
        case .accept:
            writeInt(&buf, Int32(4))
        
        
        case .remove:
            writeInt(&buf, Int32(5))
        
        
        case .block:
            writeInt(&buf, Int32(6))
        
        
        case .report:
            writeInt(&buf, Int32(7))
        
        
        case .deleteAccount:
            writeInt(&buf, Int32(8))
        
        
        case .registerPush:
            writeInt(&buf, Int32(9))
        
        
        case .publishPrekeys:
            writeInt(&buf, Int32(10))
        
        }
    }
}


