         * Why.
         */message: String
    )
    /**
     * The store refused.
     */
    case Store(
        /**
         * Why.
         */message: String
    )
    /**
     * Stored state could not be read.
     */
    case State(
        /**
         * Why.
         */message: String
    )
    /**
     * A protocol operation failed.
     */
    case Protocol(
        /**
         * Why.
         */message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

