/**
 * One thing for the shell to do, in order.
 */

public enum Effect: Equatable, Hashable {
    
    /**
     * One HTTPS request; answer with `on_http`.
     */
    case http(
        /**
         * Correlates the answer.
         */req: UInt64, 
        /**
         * Method.
         */method: Method, 
        /**
         * Path on the home server.
         */path: String, 
        /**
         * Bearer token.
         */authorization: String?, 
        /**
         * JSON body.
         */body: Data
    )
    /**
     * Open a connection; answer with `on_opened` or `on_closed`.
     */
    case `open`(
        /**
         * The connection.
         */conn: UInt64, 
        /**
         * Where.
         */endpoint: Endpoint
    )
    /**
     * Write bytes.
     */
    case write(
        /**
         * The connection.
         */conn: UInt64, 
        /**
         * Already framed and encrypted.
         */bytes: Data
    )
    /**
     * Close a connection.
     */
    case close(
        /**
         * The connection.
         */conn: UInt64
    )
    /**
     * Call `tick` at or after this time.
     */
    case timer(
        /**
         * Unix milliseconds.
         */at: Int64
    )
    /**
     * Prompt the user, then `unlock`.
     */
    case needUnlock(
        /**
         * What for.
         */reason: UnlockReason
    )
    /**
     * A message to show.
     */
    case messageAdded(
        /**
         * The message.
         */message: Message
    )
    /**
     * An outgoing message moved forward.
     */
    case messageStatus(
        /**
         * Which.
         */msgId: String, 
        /**
         * Its new status.
         */status: Delivery
    )
    /**
     * Read `friends`.
     */
    case friendsChanged
    /**
     * Read `invites`.
     */
    case invitesChanged
    /**
     * A friend came online or left.
     */
    case presenceChanged(
        /**
         * The friend.
         */peer: String, 
        /**
         * Online.
         */online: Bool
    )
    /**
     * The link's state.
     */
    case connection(
        /**
         * The state.
         */state: ConnState
    )
    /**
     * The device key's tier changed.
     */
    case tierChanged(
        /**
         * The tier.
         */tier: Tier
    )
    /**
     * Show a notification for a friend; never content.
     */
    case notify(
        /**
         * The friend.
         */peer: String
    )
    /**
     * The server refused an action.
     */
    case actionFailed(
        /**
         * Which.
         */action: Action, 
        /**
         * HTTP status; 0 when unreachable.
         */status: UInt16, 
        /**
         * The server's code.
         */code: String
    )
    /**
     * The account and this profile's data are gone.
     */
    case accountDeleted
    /**
     * An inbound frame was dropped, for the protocol log.
     */
    case dropped(
        /**
         * Why.
         */reason: String
    )
    /**
     * The store refused a write; warn the user.
     */
    case storageFailed(
        /**
         * What, and why.
         */reason: String
    )





}

